import React from "react";
import { motion } from "framer-motion";
import "./Hero.css";

const Hero = () => {
  const fadeInUp = {
    hidden: { opacity: 0, y: 50 },
    visible: { opacity: 1, y: 0, transition: { duration: 1 } },
  };

  return (
    <motion.section
      className="hero-container"
      id="home"
      initial="hidden"
      animate="visible"
    >
      <motion.div className="hero-content" variants={fadeInUp}>
        <h2>Hello, My name is Gifar</h2>
        <p>
          I'm a Frontend Developer, and I'm still learning React. I was born in
          Banjar City on the twenty-first of September two thousand and seven,
          and currently I live in Mekarharja Village, Purwaharja District,
          Banjar City. I am a student at SMK Negeri 1 Banjar.
        </p>
      </motion.div>

      <motion.div className="hero-img" variants={fadeInUp}>
        <div className="orbit-container">
          <motion.div
            className="orbit"
            animate={{ rotate: 360 }}
            transition={{ repeat: Infinity, duration: 6, ease: "linear" }}
          >
            <img
              src="./assets/images/react.png"
              className="orbit-icon"
              alt="React"
            />
            <img
              src="./assets/images/html.png"
              className="orbit-icon"
              alt="HTML"
            />
            <img
              src="./assets/images/css.png"
              className="orbit-icon"
              alt="CSS"
            />
            <img
              src="./assets/images/js.png"
              className="orbit-icon"
              alt="JavaScript"
            />
            <img
              src="./assets/images/flutter.png"
              className="orbit-icon"
              alt="Flutter"
            />
            <img
              src="./assets/images/python.png"
              className="orbit-icon"
              alt="Python"
            />
          </motion.div>
        </div>
        <img
          src="./assets/images/GIFARKASEP.jpg"
          className="profile-img"
          alt="Gifarkasep"
        />
      </motion.div>
    </motion.section>
  );
};

export default Hero;
