import React from "react";
import "./Portfolio.css";

const Portfolio = () => {
  const projects = [
    {
      title: "Project 1",
      github: "https://projek1-gifarkasep.netlify.app/",
      image: "./assets/images/P1.jpg",
    },
    {
      title: "Project 2",
      github: "https://project2-mgifar.netlify.app/",
      image: "./assets/images/P2.jpg",
    },
    {
      title: "Project 3",
      github: "https://project3-muhammadgifar.netlify.app/",
      image: "./assets/images/P3.jpg",
    },
    {
      title: "Optik Banjar Website",
      github: "https://optikbanjar.netlify.app/",
      image: "./assets/images/Optik.jpg",
    },
    {
      title: "Sertifikat HRSB",
      github: "#",
      image: "./assets/images/SERTIFIKAT HR.jpg",
    },
    {
      title: "Sertifikat ODT",
      github: "#",
      image: "./assets/images/SERTIFIKAT ODT.jpg",
    },
  ];

  return (
    <section className="portfolio-section" id="portfolio">
      <div className="container">
        <h2 className="section-title">Portfolio</h2>
        <div className="portfolio-grid">
          {projects.map((project, index) => (
            <div key={index} className="portfolio-card">
              <img
                src={project.image}
                alt={project.title}
                className="portfolio-image"
              />
              <h3 className="portfolio-title">{project.title}</h3>
              <div className="portfolio-links">
                <a
                  href={project.github}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <button className="hire-me-button">View Project</button>
                </a>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Portfolio;
