import React from "react";
import { Link, scroller } from "react-scroll"; // Import scroller dari react-scroll
import "./MobileNav.css";

const MobileNav = ({ isOpen, toggleMenu }) => {
  // Fungsi untuk scroll ke bagian Contact
  const handleScrollToContact = () => {
    scroller.scrollTo("contact", {
      smooth: true,
      duration: 500,
    });
    toggleMenu(); // Tutup menu setelah klik
  };

  return (
    <>
      <div className={`mobile-menu ${isOpen ? "active" : ""}`}>
        <div className="mobile-menu-container">
          <img className="logo" src="./assets/images/logogifar.png" alt="" />

          <ul>
            <li>
              <Link
                to="home"
                smooth={true}
                duration={500}
                onClick={toggleMenu}
                className="menu-item"
              >
                Home
              </Link>
            </li>
            <li>
              <Link
                to="skills"
                smooth={true}
                duration={500}
                onClick={toggleMenu}
                className="menu-item"
              >
                Skills
              </Link>
            </li>
            <li>
              <Link
                to="experience"
                smooth={true}
                duration={500}
                onClick={toggleMenu}
                className="menu-item"
              >
                Work Experience
              </Link>
            </li>
            <li>
              <Link
                className="menu-item"
                to="portfolio"
                smooth={true}
                duration={500}
              >
                Portfolio
              </Link>
            </li>
            <li>
              <Link
                to="contact"
                smooth={true}
                duration={500}
                onClick={toggleMenu}
                className="menu-item"
              >
                Contact Me
              </Link>
            </li>
          </ul>

          {/* Tombol "Hire Me" untuk scroll ke Contact */}
          <button className="contact-btn" onClick={handleScrollToContact}>
            Hire Me
          </button>
        </div>
      </div>
    </>
  );
};

export default MobileNav;
